      const query = `${project.referenceSongTitle || ''} ${project.referenceArtist || ''}`.trim() || `${project.genre} ${project.mood} music`;
      window.open(`https://www.youtube.com/results?search_query=${encodeURIComponent(query)}`, '_blank');
