                            style={{ width: '100%', padding: '8px', backgroundColor: '#374151', border: 'none', color: 'white', borderRadius: '4px', fontSize: '13px', boxSizing: 'border-box' }}
                        />
                        <div style={{ marginTop: '8px' }}>
                           <button 
