                </button>
                <button
                    onClick={() => setSelectedModel('gemini-3-flash-preview')}
                    style={{
                        flex: 1, padding: '10px', borderRadius: '6px',
                        border: selectedModel === 'gemini-3-flash-preview' ? '1px solid #fbbf24' : '1px solid #4b5563',
