                  <Icon name="description" />
              </div>
              <div>
                  <h3 style={{ margin: '0 0 10px 0', fontSize: '20px', color: 'white' }}>메타데이터 초안 생성</h3>
                  <p style={{ margin: 0, fontSize: '14px', color: legibilityMode ? '#E5E7EB' : '#9ca3af', lineHeight: '1.6' }}>Suno 업로드를 위한 제목, 가사, 태그를 생성합니다.</p>
              </div>
          </div>
      </div>
    </div>
  );
};

