import React, { useState, useEffect } from 'react';
import ReactDOM from 'react-dom/client';
import { GoogleGenerativeAI } from '@google/generative-ai';
import { SamplePrompt } from './types';
import Header from './components/Header';
import { getGenAI } from './utils';
import './index.css';

function App() {
  const [model, setModel] = useState<GoogleGenerativeAI | null>(null);
  const [apiKeyReady, setApiKeyReady] = useState<boolean>(false);
  const [apiKeyError, setApiKeyError] = useState<string | null>(null);
  const [selectedPrompt, setSelectedPrompt] = useState<SamplePrompt | null>(null);
  const [responseText, setResponseText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedLanguage, setSelectedLanguage] = useState<string>('en');

  useEffect(() => {
    async function checkApiKey() {
      if (window.aistudio && await window.aistudio.hasSelectedApiKey()) {
          setApiKeyReady(true);
      } else {
        setApiKeyReady(false);
      }
    }
    checkApiKey();
  }, []);

  useEffect(() => {
    async function initializeModel() {
      if (apiKeyReady) {
          try {
              const genAI = await getGenAI();
              setModel(genAI);
              setApiKeyError(null);
          } catch (error) {
              setApiKeyReady(false);
              setApiKeyError('Invalid API Key. Please select your API key in the AI Studio environment.');
          }
      }
    }
    initializeModel();
  }, [apiKeyReady]);

  async function handlePromptClick(prompt: SamplePrompt) {
    if (!model || !apiKeyReady) {
      if (!apiKeyReady) {
          if (window.aistudio) {
            await window.aistudio.openSelectKey();
            // Refresh to re-initialize model
            window.location.reload();
          } else {
            console.error('AI Studio is not available.');
          }
      }
      return;
    }
    setSelectedPrompt(prompt);
  }

  useEffect(() => {
    async function getResponse() {
      if (!model || !selectedPrompt) return;

      setIsLoading(true);
      setResponseText('');

      try {
        const result = await model.getGenerativeModel({ model: 'gemini-pro' })
            .generateContent(selectedPrompt.text);
        const response = result.response;
        setResponseText(response.text());
      } catch (error: any) {
        setApiKeyError(`Error generating content: ${error.message}`);
      } finally {
        setIsLoading(false);
      }
    }

    getResponse();
  }, [model, selectedPrompt]);

  return (
    <div className="App">
      <Header />
      {apiKeyError && <div className="error-message">{apiKeyError}</div>}
      <div className="prompt-container">
        {/* Sample Prompts */}
      </div>
      {isLoading && <div className="loading">Loading...</div>}
      {responseText && (
        <div className="response-container">
          <h2>Response:</h2>
          <pre className="response-text">{responseText}</pre>
        </div>
      )}
    </div>
  );
}

const root = ReactDOM.createRoot(document.getElementById('root')!);
root.render(<App />);
