                        <span key={idx} style={{ 
                            fontSize: '12px', padding: '4px 8px', borderRadius: '12px', 
                            backgroundColor: 'rgba(239, 68, 68, 0.2)', color: '#fca5a5', border: '1px solid rgba(239, 68, 68, 0.4)',
