    const selected = e.target.value;
    if (selected === 'Custom') {
      setNewProjectForm({ ...newProjectForm, genre: selected, subGenre: '' });
    } else {
      const genreObj = GENRES.find(g => g.label === selected);
      setNewProjectForm({ 
        ...newProjectForm, 
        genre: selected, 
        subGenre: genreObj && genreObj.subgenres.length > 0 ? genreObj.subgenres[0] : '' 
      });
