                        <div style={{ 
                            fontSize: '13px', color: '#e5e7eb', lineHeight: '1.6', 
                            maxHeight: '400px', overflowY: 'auto', paddingRight: '10px',
                            whiteSpace: 'pre-wrap'
                        }}>
                            {project.compositionAdvice}
