                        />
                        <button 
                            onClick={handleSaveInstrumentPreset}
                            style={{ padding: '0 12px', backgroundColor: '#e11d48', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '11px' }}
