                              <button 
                                onClick={() => applyInstrumentPreset(p)}
                                style={{ 
                                    padding: '6px 28px 6px 12px', 
                                    backgroundColor: '#374151', 
                                    border: '1px solid #4b5563',
                                    borderRadius: '15px',
                                    color: '#FFFFFF',
                                    fontSize: '11px',
                                    cursor: 'pointer',
                                    transition: 'all 0.2s'
                                }}
