                  <span className="material-symbols-outlined">auto_awesome</span> 생성 (Prompt)
              </h2>

              {/* Version Selector */}
              <div style={{ display: 'flex', backgroundColor: '#111827', padding: '4px', borderRadius: '8px', gap: '4px', border: '1px solid #374151' }}>
