                                    fontSize: '11px', padding: '3px 8px', borderRadius: '10px', 
                                    border: currentExcluded.includes(preset) ? '1px solid #ef4444' : '1px solid #4b5563', 
                                    backgroundColor: currentExcluded.includes(preset) ? 'rgba(239, 68, 68, 0.1)' : 'transparent',
