                          <strong>주제:</strong> {pack.topic}
                      </div>
                      <div style={{ fontSize: '11px', color: legibilityMode ? '#E5E7EB' : '#9ca3af', display: '-webkit-box', WebkitLineClamp: '2', WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>
