                            <span className="material-symbols-outlined">close</span>
                        </button>
                    </div>

                    <div style={{ color: '#d1d5db' }}>
                        <p style={{ fontSize: '13px', color: labelColor, marginBottom: '15px' }}>
                            Suno.ai에서 선호하는 음악을 만들기 위한 추천 설정값입니다.
                        </p>
                        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '13px' }}>
                            <thead>
                                <tr style={{ borderBottom: '1px solid #4b5563', color: '#e11d48' }}>
                                    <th style={{ padding: '10px', textAlign: 'left' }}>장르 (Genre)</th>
                                    <th style={{ padding: '10px', textAlign: 'left' }}>BPM Range</th>
                                    <th style={{ padding: '10px', textAlign: 'left' }}>추천 Key</th>
                                </tr>
                            </thead>
                            <tbody>
                                {DANCE_GUIDE.map((item, idx) => (
                                    <tr key={idx} style={{ borderBottom: '1px solid #374151' }}>
                                        <td style={{ padding: '10px', fontWeight: 'bold', color: '#FFFFFF' }}>{item.genre}</td>
                                        <td style={{ padding: '10px', color: '#fbbf24' }}>{item.bpm}</td>
                                        <td style={{ padding: '10px', color: '#FFFFFF' }}>{item.key}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>

                    <div style={{ display: 'flex', justifyContent: 'center', marginTop: '20px' }}>
                        <button 
                            onClick={() => setIsDanceGuideOpen(false)}
                            style={{ padding: '8px 24px', backgroundColor: '#e11d48', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}
                        >
                            확인 (Close)
                        </button>
                    </div>
                </div>
            </div>
        )}
      </div>
  );
};

export default SoundTab;

export type ViewState = 'DASHBOARD' | 'STUDIO';
export type StudioTab = 'CONCEPT' | 'STRUCTURE' | 'LYRICS' | 'SOUND' | 'ART' | 'EXPORT';

export interface ThemePack {
  title: string;
  topic: string;
  style: string;
}

export interface ReferenceSuggestion {
  song: string;
  artist: string;
}

export interface InstrumentPreset {
  name: string;
  instruments: string[];
}

export interface SongBlock {
  id: string;
  type: string;
  description: string;
  duration: number;
}

export interface Project {
  id: string;
  title: string;
  genre: string;
  subGenre: string;
  mood: string;
  styleDescription: string;
  bpm: number;
  key: string;
  createdAt: number;

  // Reference Song
  referenceSongTitle?: string;
  referenceArtist?: string;

  // Generated Content
  concept?: string;
  generatedTitles: string[];
  generatedThemePacks?: ThemePack[]; // Persist AI Idea Packs
  themePackGenerationCount?: number;
  structure: SongBlock[];
  lyrics: string;
  excludedThemes?: string;
  sunoPrompt: string;
  coverImage?: string;
  compositionAdvice?: string; // AI Music Composition Suggestions

  // Lyric Ideas Persistence
  lyricVariations?: {title: string, lyrics: string, rationale: string}[];
  selectedLyricVariationIndex?: number | null;

  // Lyric Settings Persistence (New)
  lyricLanguage?: string;
  lyricDuration?: number;
  lyricDanceMode?: boolean;
  lyricAutoAdjust?: boolean;

  // Settings
  instruments: string[];
  vocalType: string;
  djName?: string;
  introStyle?: string;
  selectedSoundPreset?: string; // Persist Sound Preset Selection

  // Structure Template Persistence
  selectedStructureTemplate?: string;
}

export interface SamplePrompt {
    label: string;
    text: string;
}

