                            {MOODS.map(m => <option key={m.id} value={m.label}>{m.label} ({m.ko})</option>)}
                        </select>
                    </div>
                </div>
                <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '10px' }}>
